int[] pre = new int[N];
int[] suf = new int[N];
pre[0] = A[0];
for (int i = 1; i < N; i++) pre[i] = gcd(pre[i - 1], A[i]);
suf[N - 1] = A[N - 1];
for (int i = N - 2; i >= 0; i--) suf[i] = gcd(suf[i + 1], A[i]);
int best = 0;
for (int i = 0; i < N; i++) {
    int cur;
    if (i == 0) cur = suf[1];
    else if (i == N - 1) cur = pre[N - 2];
    else cur = gcd(pre[i - 1], suf[i + 1]);
    best = Math.max(best, cur);
}

boolean[] composite = new boolean[N + 1];
for (int i = 2; (long) i * i <= N; i++) {
    if (!composite[i]) {
        for (long j = (long) i * i; j <= N; j += i) composite[(int) j] = true;
    }
}
// primes are indices i>=2 with !composite[i]

long mulmod(long a, long b, long m) {
    long result = 0; a %= m;
    while (b > 0) {
        if ((b & 1) == 1) result = (result + a) % m;
        a = (a + a) % m;
        b >>= 1;
    }
    return result;
}
